// Startup self-check. Before a device's first decode, a few small built-in JPEGs are decoded on that GPU; before its
// first encode, two synthetic images are encoded. The SHA-256 of each output is compared with libjpeg-turbo's
// (stored in SelfCheckData.swift, generated by `ejm selfcheck-gen`; libjpeg-turbo, not the GPU, made every JPEG and
// hash there). If anything differs, or the GPU reports an error, every decoder and encoder on that device declines
// all work for the rest of the process, so callers fall back to their CPU codec. This guards against a GPU, OS or
// shader compiler that silently changes the output.

import CryptoKit
import Foundation
import Metal
import os

/// Thrown by the encoder when the device's startup self-check failed: the GPU output did not match libjpeg-turbo,
/// so the encoder declines all work. `description`: "self-check failed on <GPU name>, <OS version>: <case>".
public struct SelfCheckFailed: Error, CustomStringConvertible {
    public let description: String
    init(_ s: String) { description = s }
}

/// One built-in decode case: a libjpeg-turbo JPEG (base64) and the SHA-256 of libjpeg-turbo's decode to `format`.
struct SelfCheckDecodeCase { let name: String; let format: PixelFormat; let sha256: String; let jpeg: String }

/// One built-in encode case: SelfCheckTesting.pixels at this size and layout, and the SHA-256 of libjpeg-turbo's
/// JPEG file for it. twoPass: encode with fusedMaxBlocks = 0, so the image is above it (the two-pass entropy path).
struct SelfCheckEncodeCase {
    let name: String; let width: Int, height: Int, channels: Int, rowBytes: Int, quality: Int
    let subsampling: Subsampling; let twoPass: Bool; let sha256: String
}

/// Hooks for `ejm` (tests and `ejm selfcheck-gen`), not a stable interface.
@_spi(Testing) public enum SelfCheckTesting {
    /// How many times the decode half of the self-check has run in this process (all devices).
    public static var decodeRuns: Int { SelfCheckRegistry.shared.runs.decode }
    /// How many times the encode half has run in this process (all devices).
    public static var encodeRuns: Int { SelfCheckRegistry.shared.runs.encode }
    /// Synchronisation passes of the decode half's small-chunk decode (0 until it has run); written under the
    /// registry lock while the decode half runs.
    nonisolated(unsafe) public static var smallChunkPasses = 0
    /// The chunk sizes (bits) the decode half's decodes used, in order (empty until it has run); written under the
    /// registry lock while the decode half runs.
    nonisolated(unsafe) public static var chunkBitsUsed: [Int] = []
    /// The built-in decode cases: name and JPEG.
    public static var decodeCases: [(name: String, jpeg: Data)] {
        SelfCheckData.decodeCases.map { ($0.name, Data(base64Encoded: $0.jpeg, options: .ignoreUnknownCharacters) ?? Data()) }
    }
    /// The built-in encode cases: name, size, layout, quality, subsampling and whether it runs the two-pass path.
    public static var encodeCases: [(name: String, width: Int, height: Int, channels: Int, rowBytes: Int, quality: Int,
                                     subsampling: Subsampling, twoPass: Bool)] {
        SelfCheckData.encodeCases.map { ($0.name, $0.width, $0.height, $0.channels, $0.rowBytes, $0.quality, $0.subsampling, $0.twoPass) }
    }

    /// The synthetic image of every built-in case (the same formula as the CUDA sibling's self-check): for pixel
    /// (x, y) and channel c in 0...2, v = (x*7 + y*13 + c*61 + ((x*y) >> 3)) & 255, plus 40 where
    /// ((x >> 4) + (y >> 4)) is even and minus 40 elsewhere, clamped to 0...255. RGB first, `channels` (3 or 4)
    /// bytes per pixel, rows `rowBytes` apart; the fourth channel and row padding are 0x5A. A gray source is c = 0.
    public static func pixels(width w: Int, height h: Int, channels: Int, rowBytes rb: Int) -> [UInt8] {
        var p = [UInt8](repeating: 0x5A, count: rb * (h - 1) + w * channels)
        for y in 0..<h {
            for x in 0..<w {
                let d = ((x >> 4) + (y >> 4)) & 1 == 0 ? 40 : -40
                for c in 0..<3 {
                    let v = ((x * 7 + y * 13 + c * 61 + ((x * y) >> 3)) & 255) + d
                    p[y * rb + x * channels + c] = UInt8(min(max(v, 0), 255))
                }
            }
        }
        return p
    }
}

/// Per-device results, shared by every MetalContext on that device in the process.
final class SelfCheckRegistry: @unchecked Sendable {
    static let shared = SelfCheckRegistry()
    final class State: @unchecked Sendable {
        let lock = NSLock()            // held while a half runs: concurrent first callers wait here
        var decodeDone = false, encodeDone = false
        var failure: String?
        // Fast-path flags, read without `lock` (which a running half holds): true once that half passed and while
        // nothing has failed. A failure in either half clears both, so a broken GPU path is not trusted for anything.
        // Behind their own os_unfair_lock (uncontended: a few ns per call), so the read is never a data race.
        private let flagLock = UnsafeMutablePointer<os_unfair_lock>.allocate(capacity: 1)
        private var _decodeOK = false, _encodeOK = false
        init() { flagLock.initialize(to: os_unfair_lock()) }
        deinit { flagLock.deinitialize(count: 1); flagLock.deallocate() }
        var decodeOK: Bool {
            get { os_unfair_lock_lock(flagLock); defer { os_unfair_lock_unlock(flagLock) }; return _decodeOK }
            set { os_unfair_lock_lock(flagLock); _decodeOK = newValue; os_unfair_lock_unlock(flagLock) }
        }
        var encodeOK: Bool {
            get { os_unfair_lock_lock(flagLock); defer { os_unfair_lock_unlock(flagLock) }; return _encodeOK }
            set { os_unfair_lock_lock(flagLock); _encodeOK = newValue; os_unfair_lock_unlock(flagLock) }
        }
    }
    private let lock = NSLock()
    private var states: [UInt64: State] = [:]
    private var decodeRuns = 0, encodeRuns = 0
    var runs: (decode: Int, encode: Int) { lock.lock(); defer { lock.unlock() }; return (decodeRuns, encodeRuns) }

    func state(_ device: MTLDevice) -> State {
        lock.lock(); defer { lock.unlock() }
        if let s = states[device.registryID] { return s }
        let s = State()
        states[device.registryID] = s
        return s
    }
    func countRun(decode: Bool) { SetupWork.bump(); lock.lock(); if decode { decodeRuns += 1 } else { encodeRuns += 1 }; lock.unlock() }
}

/// EJM_SELFCHECK_FAIL=1, read once per process (the first time a half of the self-check runs)
let selfCheckForcedFailure = ProcessInfo.processInfo.environment["EJM_SELFCHECK_FAIL"] == "1"

/// "macOS 27.2 (26B123)": the OS name, version and build
private let osDescription: String = {
    let v = ProcessInfo.processInfo.operatingSystemVersion
    #if os(iOS)
    let name = "iOS"
    #else
    let name = "macOS"
    #endif
    var buf = [CChar](repeating: 0, count: 64), n = 64
    let build = sysctlbyname("kern.osversion", &buf, &n, nil, 0) == 0 ? String(decoding: buf.prefix { $0 != 0 }.map { UInt8(bitPattern: $0) }, as: UTF8.self) : "unknown build"
    return "\(name) \(v.majorVersion).\(v.minorVersion)\(v.patchVersion > 0 ? ".\(v.patchVersion)" : "") (\(build))"
}()

extension MetalContext {
    /// Runs this device's self-check, the decode half and / or the encode half, unless it already ran in this
    /// process (each half once per process per device; concurrent first callers wait for one run). Returns nil when
    /// it passed, else the reason decoders and encoders give: "self-check failed on <GPU name>, <OS version>: <case>".
    /// A failure in either half fails both. Decoders run the decode half before their first decode, encoders the
    /// encode half before their first encode, and warmUp() runs both.
    public func selfCheck(decode: Bool = true, encode: Bool = true) -> String? {
        let st = selfCheckState
        if (!decode || st.decodeOK) && (!encode || st.encodeOK) { return nil }
        st.lock.lock(); defer { st.lock.unlock() }
        if st.failure == nil && decode && !st.decodeDone {
            SelfCheckRegistry.shared.countRun(decode: true)
            st.failure = runDecodeHalf()
            st.decodeDone = true
        }
        if st.failure == nil && encode && !st.encodeDone {
            SelfCheckRegistry.shared.countRun(decode: false)
            st.failure = runEncodeHalf()
            st.encodeDone = true
        }
        if st.failure == nil && selfCheckForcedFailure {
            st.failure = selfCheckReason("forced by EJM_SELFCHECK_FAIL=1")
        }
        if let f = st.failure { st.decodeOK = false; st.encodeOK = false; return f }
        st.decodeOK = st.decodeDone; st.encodeOK = st.encodeDone
        return nil
    }

    private func selfCheckReason(_ what: String) -> String { "self-check failed on \(device.name), \(osDescription): \(what)" }

    private static func hex(_ d: SHA256.Digest) -> String { d.map { String(format: "%02x", $0) }.joined() }

    private func runDecodeHalf() -> String? {
        let dec = Decoder(ctx: self)
        dec.selfCheckExempt = true; dec.internalUse = true
        dec.checkpoints = 7                                  // the default, whatever EJM_NCP says
        for c in SelfCheckData.decodeCases {
            guard let jpeg = Data(base64Encoded: c.jpeg, options: .ignoreUnknownCharacters) else {
                return selfCheckReason(c.name + " (embedded data unreadable)")
            }
            // the default chunk size for this stream (2048 bits below Decoder.smallStream: every case here), whatever
            // EJM_CHUNK_BITS says
            let s0 = (try? jpeg.withUnsafeBytes { try parseJPEGHeader($0) })?.scanStart ?? 0
            dec.chunkBits = Decoder.defaultChunkBits(jpeg.count - s0)
            SelfCheckTesting.chunkBitsUsed.append(dec.chunkBits ?? 0)
            guard let img = dec.decode(jpeg, format: c.format) else {
                return selfCheckReason(c.name + " (declined: \(dec.reason ?? "unknown"))")
            }
            guard MetalContext.hex(SHA256.hash(data: img.bytes)) == c.sha256 else {
                return selfCheckReason(c.name + " (output differs)")
            }
            if c.name == "decode 4:2:0 without restarts" {
                // the same file in 4096-bit chunks (the default for streams of 256 KB and more), then in 64-bit chunks
                // (about 480 chunks, several threadgroups), so the work between synchronisation passes runs too; same
                // bytes required
                dec.chunkBits = 4096
                SelfCheckTesting.chunkBitsUsed.append(4096)
                guard let large = dec.decode(jpeg, format: c.format) else {
                    return selfCheckReason(c.name + ", 4096-bit chunks (declined: \(dec.reason ?? "unknown"))")
                }
                guard MetalContext.hex(SHA256.hash(data: large.bytes)) == c.sha256 else {
                    return selfCheckReason(c.name + ", 4096-bit chunks (output differs)")
                }
                dec.chunkBits = 64
                SelfCheckTesting.chunkBitsUsed.append(64)
                guard let small = dec.decode(jpeg, format: c.format) else {
                    return selfCheckReason(c.name + ", small chunks (declined: \(dec.reason ?? "unknown"))")
                }
                guard MetalContext.hex(SHA256.hash(data: small.bytes)) == c.sha256 else {
                    return selfCheckReason(c.name + ", small chunks (output differs)")
                }
                SelfCheckTesting.smallChunkPasses = dec.passes
            }
        }
        return nil
    }

    private func runEncodeHalf() -> String? {
        let enc = Encoder(ctx: self)
        enc.selfCheckExempt = true; enc.internalUse = true
        let fused = Encoder.fusedCap(device)       // both paths, whatever the profile or EJM_FUSED_MAX_BLOCKS chose
        for c in SelfCheckData.encodeCases {
            enc.fusedMaxBlocks = c.twoPass ? 0 : fused
            let px = SelfCheckTesting.pixels(width: c.width, height: c.height, channels: c.channels, rowBytes: c.rowBytes)
            let out: Data
            do {
                out = try px.withUnsafeBytes {
                    try enc.encode(bytes: $0, width: c.width, height: c.height, channels: c.channels,
                                   rowBytes: c.rowBytes, quality: c.quality, subsampling: c.subsampling)
                }
            } catch {
                return selfCheckReason(c.name + " (\(type(of: error)): \(error))")
            }
            guard MetalContext.hex(SHA256.hash(data: out)) == c.sha256 else {
                return selfCheckReason(c.name + " (output differs)")
            }
        }
        return nil
    }
}
